def apply_titles(lst, i):
    """i: 0 — укр., 1 — рос."""
    for a in lst:
        t = TITLES.get(a['slug'])
        if t:
            a['title'] = t[i]

def _mk(lang):
    out = []
    for r in _RAW:
        d = dict(r[lang]); d.update(slug=r['slug'], module=r['module'], date=r['date'])
        out.append(d)
    return out

ARTICLES_UK_MORE = _mk('uk')
ARTICLES_RU_MORE = _mk('ru')
